import { expect, test, uniqueName } from "../../fixtures";

type Doc = { id: string; status: string };
type Field = { value: string | null; confidence: number };
type Extraction = { fields: Record<string, Field> };
type QueueItem = { vendor_id: string; lowest_confidence: number; extractions: Extraction[] };

const DOCS: Array<{ kind: "w9" | "insurance_certificate" | "contract" }> = [
  { kind: "w9" },
  { kind: "insurance_certificate" },
  { kind: "contract" },
];

const minimalPdf = () => Buffer.from("%PDF-1.4\n%%EOF\n");

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  // Arrange: two vendors, each with all three documents extracted, then submitted.
  const vendorIds: string[] = [];
  for (let i = 0; i < 2; i++) {
    const create = await member.post("/api/vendors", {
      data: {
        name: uniqueName("REV03 Vendor"),
        category: "services",
        contact_email: `rev03-${Date.now().toString(36)}-${i}@example.com`,
      },
    });
    expect(create.status(), await create.text()).toBe(201);
    const vendor = await create.json();
    vendorIds.push(vendor.id);

    const docIds: string[] = [];
    for (const doc of DOCS) {
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: doc.kind,
          file: {
            name: `${doc.kind}.pdf`,
            mimeType: "application/pdf",
            buffer: minimalPdf(),
          },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);
      docIds.push(((await upload.json()) as Doc).id);
    }

    // Extraction runs in the background; wait for every document to finish.
    for (const docId of docIds) {
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${docId}`);
            expect(res.status(), await res.text()).toBe(200);
            return ((await res.json()) as Doc).status;
          },
          { timeout: 60_000 },
        )
        .toBe("extracted");
    }

    const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submit.status(), await submit.text()).toBe(200);
  }

  // Act
  const queueRes = await reviewer.get("/api/review-queue");
  expect(queueRes.status(), await queueRes.text()).toBe(200);
  const queue = (await queueRes.json()) as QueueItem[];

  // Assert: the queue is sorted by lowest confidence, ascending.
  for (let i = 1; i < queue.length; i++) {
    expect(queue[i].lowest_confidence, "queue order").toBeGreaterThanOrEqual(queue[i - 1].lowest_confidence);
  }

  // Our two vendors appear in the order of their own lowest field confidence.
  const ours = queue.filter((item) => vendorIds.includes(item.vendor_id));
  expect(ours.length, "both vendors are in the queue").toBe(2);
  const lowestOf = (item: QueueItem) =>
    Math.min(...item.extractions.flatMap((e) => Object.values(e.fields).map((f) => f.confidence)));
  const expectedFirst = [...ours].sort((a, b) => lowestOf(a) - lowestOf(b))[0];
  expect(ours[0].vendor_id).toBe(expectedFirst.vendor_id);
  expect(ours[0].lowest_confidence).toBeCloseTo(lowestOf(ours[0]), 5);
});
